import json
from pathlib import Path

questions = []

def mcq(section, number, question, options, answer, explanation, similar_question, similar_options, similar_answer, reading=None):
    item = {
        "type": "mcq", "question": f"{section} {number}. {question}",
        "options": options, "answer": answer, "marks": 1,
        "explanation": explanation, "similar_question": similar_question,
        "similar_options": similar_options,
        "similar_correct_answer": similar_answer,
    }
    if reading:
        item["reading_page"] = {"title": f"Source exam context: {section} {number}", "text": reading}
    questions.append(item)

def short(section, number, question, answer, explanation, similar_question, similar_answer, reading=None):
    item = {
        "type": "short", "question": f"{section} {number}. {question}",
        "answer": answer, "marks": 1, "explanation": explanation,
        "similar_question": similar_question,
        "similar_correct_answer": similar_answer,
    }
    if reading:
        item["reading_page"] = {"title": f"Source exam context: {section} {number}", "text": reading}
    questions.append(item)

