quiz = {
    "title": "Fun Quiz: SMIB032 2026 Main Exam Practice",
    "is_fun": True,
    "fun_level": "expert",
    "questions": questions,
}

for index, q in enumerate(questions, 1):
    assert q["type"] in ("mcq", "short"), index
    assert all(q.get(key) for key in ("question", "answer", "explanation", "similar_question", "similar_correct_answer")), index
    if q["type"] == "mcq":
        assert len(q["options"]) == 4 and len(set(q["options"])) == 4 and q["answer"] in q["options"], index
        assert len(q["similar_options"]) == 4 and len(set(q["similar_options"])) == 4 and q["similar_correct_answer"] in q["similar_options"], index
    else:
        assert len(q["answer"].split()) <= 2 and len(q["similar_correct_answer"].split()) <= 2, index

output = Path("output/arounus_smib032_2026_main_exam_fun_quiz.json")
